import {ARTICLE,DEFAULT_PARAGRAPHS,makeExercise,wordCoaches,sentenceGuide,parseImportedArticle} from './english-content.js';
import {englishTokens,estimatePitch,evaluateEnglish} from './english-evaluation.js';

const escape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=name=>`<svg aria-hidden="true"><use href="#i-${name}"/></svg>`;
const clock=s=>`${String(Math.floor(s/60)).padStart(2,'0')}:${String(Math.floor(s%60)).padStart(2,'0')}`;
const load=(key,fallback)=>{try{return JSON.parse(localStorage.getItem('yanxi-en-'+key))??fallback;}catch{return fallback;}};
const persist=(key,value)=>{try{localStorage.setItem('yanxi-en-'+key,JSON.stringify(value));return true;}catch{return false;}};

export function createEnglishModule({root,notify,onViewChange=()=>{}}){
  const defaults={articleId:ARTICLE.id,paragraphIds:DEFAULT_PARAGRAPHS,practice:'passage',sentenceIndex:0,accent:'en-US',rate:.85,guides:true};
  const settings={...defaults,...load('settings',{})};
  if(!['en-US','en-GB'].includes(settings.accent))settings.accent='en-US';
  if(![.75,.85,1].includes(Number(settings.rate)))settings.rate=.85;
  if(!['sentence','passage'].includes(settings.practice))settings.practice='passage';
  const storedArticles=load('articles',[]),storedHistory=load('history',[]),storedFavorites=load('favorites',[]);
  let articles=Array.isArray(storedArticles)?storedArticles.filter(a=>a?.id&&Array.isArray(a.paragraphs)).slice(0,10):[];
  let records=Array.isArray(storedHistory)?storedHistory.filter(r=>r?.id&&r?.exercise&&r?.analysis).slice(0,30):[];
  let favorites=Array.isArray(storedFavorites)?storedFavorites.filter(f=>f?.id&&f?.exercise).slice(0,100):[];
  let temporaryArticle=null,page='practice',session=null,pending=false,playing=false,report=null,audioURL=null,error='',sampleTime=0;
  const memoryAudio=new Map();let dbPromise;
  const dialog=document.createElement('dialog');dialog.id='en-sheet';dialog.className='en-dialog';dialog.setAttribute('aria-labelledby','en-sheet-title');document.body.append(dialog);
  const q=selector=>root.querySelector(selector);
  function article(){return [ARTICLE,...articles,temporaryArticle].find(a=>a?.id===settings.articleId)||ARTICLE;}
  function exercise(){return makeExercise(article(),Array.isArray(settings.paragraphIds)?settings.paragraphIds:DEFAULT_PARAGRAPHS,settings.practice,settings.sentenceIndex);}
  function save(){persist('settings',settings);}
  function isBusy(){return Boolean(session||pending);}
  function locked(){if(isBusy()){notify('请先结束英语练习，再进行切换');return true;}return false;}
  function database(){if(!dbPromise)dbPromise=new Promise((resolve,reject)=>{const request=indexedDB.open('yanxi-en-audio',1);request.onupgradeneeded=()=>request.result.createObjectStore('recordings');request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error);request.onblocked=()=>reject(new Error('storage unavailable'));});return dbPromise;}
  async function audioStore(action,id,blob){try{const db=await database();return await new Promise((resolve,reject)=>{const tx=db.transaction('recordings',action==='get'?'readonly':'readwrite'),store=tx.objectStore('recordings');const request=action==='get'?store.get(id):action==='put'?store.put(blob,id):store.delete(id);let result;request.onsuccess=()=>result=request.result;request.onerror=()=>reject(request.error);tx.oncomplete=()=>resolve(action==='get'?result:true);tx.onabort=tx.onerror=()=>reject(tx.error);});}catch{return action==='get'?null:false;}}
  function stopPlayback(){if('speechSynthesis'in window)speechSynthesis.cancel();playing=false;dialog.querySelector('audio')?.pause();const label=q('[data-en-action="listen"] span');if(label)label.textContent='听示范';}
  function closeDialog(){dialog.querySelector('audio')?.pause();dialog.close();report=null;if(audioURL){URL.revokeObjectURL(audioURL);audioURL=null;}}
  function showDialog(title,body){dialog.innerHTML=`<div class="sheet-handle"></div><div class="sheet-heading"><h2 id="en-sheet-title">${escape(title)}</h2><button class="icon-button" data-en-action="close" aria-label="关闭英语面板">${icon('close')}</button></div>${body}`;if(!dialog.open)dialog.showModal();dialog.scrollTop=0;}
  function referenceText(text){
    if(!settings.guides)return escape(text);
    const strong=new Set(['school','homework','music','play','unstructured','fallow','vital','friendships','tasks','deadlines','pressures','secret','friendship','device','engage','person','quality','relationships','social','lonely','connected']);
    return text.split(/(\b[a-z]+(?:[’'][a-z]+)?\b|[,;:—])/i).map(part=>{if(strong.has(part.toLowerCase()))return `<strong>${escape(part)}</strong>`;if(/^[,;:—]$/.test(part))return escape(part)+'<span class="en-boundary" aria-hidden="true"> / </span>';return escape(part);}).join('');
  }
  function dailyMinutes(){const today=new Date().toLocaleDateString('zh-CN');return Math.floor(records.filter(r=>new Date(r.date).toLocaleDateString('zh-CN')===today).reduce((n,r)=>n+r.duration,0)/60);}
  function practiceHTML(){const ex=exercise(),a=article(),words=englishTokens(ex.text).length,saved=favorites.some(f=>f.exercise.articleId===ex.articleId&&f.exercise.paragraphIds.join(',')===ex.paragraphIds.join(','));const coach=wordCoaches(ex.paragraphs.map(p=>p.text).join(' '));
    return `<div class="en-page section-fade"><section class="hero en-hero"><div class="eyebrow">ONE SENTENCE AT A TIME</div><h1>把英语，<br><span>说得更自然。</span></h1><p class="hero-sub">听清 · 跟读 · 回听 · 再说一次</p><div class="en-hero-art" aria-hidden="true">Aa<span>↗</span><i>↘</i></div></section><div class="en-summary"><span class="pill green">英语 · 基础纠音</span><span>今天已练 ${dailyMinutes()} 分钟</span></div><div class="section-heading"><h2>从你正在读的文章开始</h2><button class="text-button" data-en-action="choose">${icon('tune')}选文 / 换段</button></div><div class="en-material-meta"><span>第 ${ex.paragraphIds.join('、')} 自然段 · ${englishTokens(ex.paragraphs.map(p=>p.text).join(' ')).length} 词</span><button class="text-button" data-en-action="full-article">查看纯净全文 ${icon('chevron')}</button></div><article class="reading-card en-reading-card"><div class="card-top"><span class="card-label">YOUR ARTICLE / READ & CONNECT</span><button class="favorite-button ${saved?'saved':''}" data-en-action="favorite" aria-label="${saved?'取消收藏英语选段':'收藏英语选段'}">${icon('bookmark')}</button></div><h3 lang="en">${escape(a.title)}</h3><p class="en-source">${a.id===ARTICLE.id?'开源版原创练习文章 · MIT 许可':escape(a.source)}</p><div class="en-practice-tabs" role="group" aria-label="英语练习方式"><button data-en-practice="passage" aria-pressed="${settings.practice==='passage'}" class="${settings.practice==='passage'?'active':''}">整段朗读</button><button data-en-practice="sentence" aria-pressed="${settings.practice==='sentence'}" class="${settings.practice==='sentence'?'active':''}">逐句跟读</button></div>${settings.practice==='sentence'?`<div class="en-sentence-label"><span>第 ${ex.sentenceIndex+1} / ${ex.sentences.length} 句 · 原文第 ${ex.sentences[ex.sentenceIndex].paragraphId} 段</span><span>${words} 词</span></div><div class="en-article en-current-sentence" lang="en">${referenceText(ex.text)}</div><div class="en-sentence-nav"><button class="simple-button" data-en-action="previous" ${ex.sentenceIndex===0?'disabled':''}>上一句</button><span class="en-sentence-progress">${ex.sentences.map((_,i)=>`<i class="${i===ex.sentenceIndex?'active':''}"></i>`).join('')}</span><button class="simple-button" data-en-action="next" ${ex.sentenceIndex===ex.sentences.length-1?'disabled':''}>下一句</button></div><p class="en-ending-guide">${sentenceGuide(ex.text).label}</p>`:`<div class="en-article" lang="en">${ex.paragraphs.map(p=>`<section><span class="en-paragraph-number">PARAGRAPH ${p.id}</span><p>${referenceText(p.text)}</p></section>`).join('')}</div>`}<div class="card-footer"><span>正文来自你的文章，未作改写</span><button class="pause-toggle ${settings.guides?'on':''}" data-en-action="guides" aria-pressed="${settings.guides}"><span class="switch"></span>意群 / 重读</button></div><p class="en-guide-note">${settings.guides?'斜线与粗体仅为跟读提示，不属于文章正文。':'先听一遍，再用自己的自然节奏朗读。'}</p></article><div class="en-voice-controls"><label><span>示范口音</span><select id="en-accent" aria-label="英语示范口音"><option value="en-US" ${settings.accent==='en-US'?'selected':''}>美式英语</option><option value="en-GB" ${settings.accent==='en-GB'?'selected':''}>英式英语</option></select></label><label><span>示范速度</span><select id="en-rate" aria-label="英语示范速度">${[[.75,'慢速 0.75×'],[.85,'舒缓 0.85×'],[1,'正常 1×']].map(([v,t])=>`<option value="${v}" ${Number(settings.rate)===v?'selected':''}>${t}</option>`).join('')}</select></label></div><div class="coach-tip">${icon('spark')}<div><strong>每次只改进一个地方。</strong>先听示范，跟着读；回听时留意词尾、关键词和句末收束。</div></div>${recordHTML()}<details class="en-coach fold"><summary>选段发音重点 <span>· 跟读提示</span></summary>${coach.length?coach.map(w=>`<div class="en-word-coach"><button data-en-word="${escape(w.word)}" aria-label="听 ${escape(w.word)} 的示范"><b lang="en">${w.word}</b>${icon('headphones')}</button><span class="en-stress-name" lang="en">${w.stress}</span>${w[settings.accent==='en-US'?'us':'uk']?`<span class="en-ipa">/${w[settings.accent==='en-US'?'us':'uk']}/</span>`:''}<p>${escape(w.tip)}</p>${w.url?`<a href="${w.url}" target="_blank" rel="noopener noreferrer">词典发音参考 ↗</a>`:''}</div>`).join(''):'<p class="small-note">先找出实词和重读音节，再把轻读部分连成意群。可以在“逐句跟读”中反复听、读、回听。</p>'}<p class="small-note">这些是根据选段准备的练习提示，未检测你是否存在相应发音问题。单词示范使用设备英语语音；口音可有合理差异。</p></details><p class="storage-note">基础版提供单词比对、语速、停顿及音高变化线索；不能判断音素、词重音是否正确，不提供专业发音总分。</p></div>`;
  }
  function recordHTML(){return `<section class="recorder ${session?'recording':''} en-recorder" aria-label="英语录音练习"><div class="timer-row"><span class="timer-dot"></span><span id="en-status-label">${session?'正在练习英语':'听一遍，然后轮到你'}</span></div><div id="en-timer" class="timer">${session?clock((performance.now()-session.start)/1000):'00:00'}</div><div class="live-wave" aria-hidden="true">${Array.from({length:17},(_,i)=>`<i style="--h:${[4,8,13,6,16,9,21,14,8,19,11,17,7,12,5,9,4][i]}px"></i>`).join('')}</div><div class="record-controls"><button class="record-side" data-en-action="listen" ${isBusy()?'disabled':''}>${icon('headphones')}<span>听示范</span></button><button class="record-main" data-en-action="record" aria-label="${session?'结束英语录音并分析':'开始英语录音'}" ${pending?'disabled':''}>${session?'<span class="stop-square"></span>':icon('mic')}</button><button class="record-side" data-en-action="choose" ${isBusy()?'disabled':''}>${icon('book')}<span>换段练习</span></button></div><p class="record-caption" id="en-record-caption">${pending?'正在准备…':session?'结束并查看纠音线索':'开始英语跟读'}</p><p class="privacy-note">录音保存在本机 · 英语转写由浏览器提供<br>转写可能依赖网络，录音分析与发音提示在本地进行</p><div class="record-status" id="en-record-status" role="status">${escape(error)}</div><div class="live-text" id="en-live" ${session?'':'hidden'}><small>ENGLISH TRANSCRIPT · 实时转写</small><span id="en-final">${escape(session?.transcript||'')}</span><span id="en-interim" class="live-interim"></span></div></section>`;}
  function render(nextPage=page){page=nextPage;onViewChange(page);if(page==='practice')root.innerHTML=practiceHTML();if(page==='history')renderHistory();if(page==='favorites')renderFavorites();}
  function renderHistory(){const total=records.reduce((n,r)=>n+r.duration,0);root.innerHTML=`<div class="en-page section-fade"><div class="page-heading"><div class="eyebrow">YOUR ENGLISH, YOUR PROGRESS</div><h1>听见自己的进步。</h1><p>英语练习单独保存，回到同一句，再试一次。</p></div><div class="stat-grid"><div class="stat"><b>${records.length}</b><span>次英语练习</span></div><div class="stat"><b>${Math.floor(total/60)}</b><span>累计分钟</span></div><div class="stat"><b>${new Set(records.map(r=>new Date(r.date).toLocaleDateString('zh-CN'))).size}</b><span>练习天数</span></div></div>${records.length?records.map(r=>`<button class="list-card" data-en-record="${r.id}"><span class="pill green">英语 · ${r.exercise.practice==='sentence'?'逐句':'整段'}</span><h3 lang="en">${escape(r.exercise.articleTitle)}</h3><div class="excerpt" lang="en">${escape(r.exercise.text)}</div><p class="mt"><span>${escape(new Date(r.date).toLocaleString('zh-CN',{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'}))} · ${clock(r.duration)}</span>${icon('chevron')}</p></button>`).join(''):`<div class="empty">${icon('headphones')}<h3>第一遍，先放轻松</h3><p>录一段英语，让自己听见变化。<br>练习结束后，纠音线索会保存在这里。</p><button class="simple-button primary" data-en-action="practice">开始练英语</button></div>`}<p class="storage-note">英语记录和录音独立保存在本机，保留最近 30 次。重要录音请下载，清理浏览器数据后不会保留。</p></div>`;}
  function renderFavorites(){root.innerHTML=`<div class="en-page section-fade"><div class="page-heading"><div class="eyebrow">SENTENCES TO COME BACK TO</div><h1>把好段落，练成自己的。</h1><p>已收藏 ${favorites.length} 组选段。</p></div>${favorites.length?favorites.map(f=>`<button class="list-card" data-en-favorite="${f.id}"><span class="pill green">第 ${f.exercise.paragraphIds.join('、')} 自然段</span><h3 lang="en">${escape(f.exercise.articleTitle)}</h3><div class="excerpt" lang="en">${escape(f.exercise.paragraphs.map(p=>p.text).join(' '))}</div><p class="mt"><span>打开并重练</span>${icon('chevron')}</p></button>`).join(''):`<div class="empty">${icon('bookmark')}<h3>留下想再读的段落</h3><p>点击英语材料右上角的收藏图标，<br>下次可以直接打开这组选段。</p><button class="simple-button primary" data-en-action="practice">去选一段</button></div>`}<p class="storage-note">英语收藏与中文收藏分别保存，最多 100 组。</p></div>`;}
  function restore(ex){const existing=[ARTICLE,...articles].find(a=>a.id===ex.articleId);if(!existing)temporaryArticle={id:ex.articleId,title:ex.articleTitle,source:'从本机练习记录恢复',paragraphs:ex.paragraphs};settings.articleId=ex.articleId;settings.paragraphIds=ex.paragraphIds;settings.practice=ex.practice;settings.sentenceIndex=ex.sentenceIndex;save();page='practice';}
  function fullArticle(){if(locked())return;stopPlayback();const a=article();showDialog('你的文章 · 纯净正文',`<p class="form-note">${escape(a.source)}${a.id===ARTICLE.id?'<br>内置文章为开源版原创练习示例，也可自行粘贴有权使用的英文材料。':''}</p><h3 class="en-full-title" lang="en">${escape(a.title)}</h3><div class="en-full-article" lang="en">${a.paragraphs.map(p=>`${p.heading?`<h4>${escape(p.heading)}</h4>`:''}<div><span>${p.id}</span><p>${escape(p.text)}</p></div>`).join('')}</div><button class="simple-button primary full mt" data-en-action="close">返回跟读</button>`);}
  function choose(draftId=settings.articleId,draftIds=settings.paragraphIds){if(locked())return;stopPlayback();const a=[ARTICLE,...articles,temporaryArticle].find(item=>item?.id===draftId)||ARTICLE;showDialog('选一到两个自然段',`<form id="en-selection"><label class="form-label" for="en-article-select">练习文章</label><select id="en-article-select" name="article">${[ARTICLE,...articles,...(temporaryArticle?[temporaryArticle]:[])].map(a=>`<option value="${escape(a.id)}" ${a.id===draftId?'selected':''}>${escape(a.title)}</option>`).join('')}</select><p class="form-note">首组推荐第 10—11 段，练习长句分组、列举重音与结尾收束。每次最多选择两个自然段。</p><div class="en-paragraph-options">${a.paragraphs.map(p=>`<label class="en-paragraph-option"><input type="checkbox" name="paragraph" value="${p.id}" ${draftIds.includes(p.id)?'checked':''}><div><b>第 ${p.id} 自然段 <small>${englishTokens(p.text).length} 词</small></b><p lang="en">${escape(p.text)}</p></div></label>`).join('')}</div><button type="submit" class="simple-button primary full mt">选好，开始练习</button></form><button class="simple-button full mt" data-en-action="import">录入另一篇英文文章</button>`);}
  function importForm(){showDialog('录入新的英文文章',`<form id="en-import"><label class="form-label" for="en-import-title">文章标题</label><input id="en-import-title" class="en-input" maxlength="100" placeholder="例如：My reading article"><label class="form-label" for="en-import-text">英文印刷正文</label><textarea id="en-import-text" required maxlength="18000" rows="10" placeholder="粘贴正文，用空行分开自然段。请勿混入手写释义或笔记。"></textarea><p class="form-note">保留自然段，最多 30 段、18000 字符。录入后可选择 1—2 段练习。自录文章只保存在当前浏览器，最多保存 10 篇。</p><button class="simple-button primary full" type="submit">保存文章并选段</button></form>`);}
  function help(){if(locked())return;stopPlayback();showDialog('英语口语 · 基础纠音',`<div class="help-block"><h3>推荐练习顺序</h3><p>先听选段示范，切到逐句跟读；看意群和关键词，完整读一句，再回听、重录。每次优先改进一处词尾、一个重读音节或一句话的收尾。</p></div><div class="help-block"><h3>哪些是实际录音线索？</h3><p>单词比对来自英语语音转写。语速为转写词数除以总录音时长。停顿和音高走势来自本机录音信号；音高曲线只表示声音变化，不判断口音优劣。</p></div><div class="help-block"><h3>哪些是跟读建议？</h3><p>粗体、意群斜线、句末语调及词语发音要点是预先准备的练习提示，未检测你是否犯了相应错误。基础版不能评定音素、词重音或语调准确度。不同口音和语境存在合理差异。</p></div><div class="help-block"><h3>文章和录音在哪里？</h3><p>内置文章为原创练习示例；自行录入的文章保存在当前浏览器。中文和英文的记录、收藏独立保存。录音保存在本机，浏览器语音识别可能把音频发送给其识别服务；识别不可用时仍可录音回听。</p></div><button class="simple-button primary full" data-en-action="close">开始练习</button>`);}
  function speak(text){if(locked())return;if(!('speechSynthesis'in window)){notify('当前浏览器不支持语音示范');return;}if(playing){stopPlayback();return;}const voices=speechSynthesis.getVoices(),voice=voices.find(v=>v.lang.toLowerCase()===settings.accent.toLowerCase())||voices.find(v=>/^en[-_]/i.test(v.lang));const utterance=new SpeechSynthesisUtterance(text);utterance.lang=settings.accent;utterance.rate=Number(settings.rate);if(voice){utterance.voice=voice;if(voice.lang.toLowerCase()!==settings.accent.toLowerCase())notify('设备没有所选口音，使用当前可用的英语声音');}utterance.onend=()=>{playing=false;const label=q('[data-en-action="listen"] span');if(label)label.textContent='听示范';};utterance.onerror=e=>{playing=false;if(!['canceled','interrupted'].includes(e.error))notify('设备暂时无法播放英语语音，请检查英语语音包');};playing=true;const label=q('[data-en-action="listen"] span');if(label)label.textContent='停止示范';speechSynthesis.cancel();speechSynthesis.speak(utterance);}
  function startRecognition(s){const Recognition=window.SpeechRecognition||window.webkitSpeechRecognition;if(!Recognition){s.recognitionStatus='当前浏览器不支持英文转写，仍可录音回听及查看声学线索。';q('#en-record-status').textContent=s.recognitionStatus;return;}const recognizer=new Recognition();s.recognizer=recognizer;recognizer.lang=settings.accent;recognizer.continuous=true;recognizer.interimResults=true;let committed='',cycle='',interim='',ended=true,retries=0;const update=()=>{s.transcript=(committed+' '+cycle).trim();const final=q('#en-final'),pendingText=q('#en-interim');if(final)final.textContent=s.transcript+' ';if(pendingText)pendingText.textContent=interim;};recognizer.onstart=()=>{ended=false;const status=q('#en-record-status');if(status)status.textContent='正在听你说英语…';};recognizer.onresult=e=>{cycle='';interim='';for(let i=0;i<e.results.length;i++){if(e.results[i].isFinal)cycle+=e.results[i][0].transcript+' ';else interim+=e.results[i][0].transcript;}update();};recognizer.onerror=e=>{if(['aborted','no-speech'].includes(e.error))return;retries+=['not-allowed','service-not-allowed','audio-capture','language-not-supported'].includes(e.error)?3:1;s.recognitionStatus=e.error==='network'?'英文识别网络不可用；本次仍可回听，语音比对可能不完整。':'英文识别服务暂不可用；本次仍可回听。';const status=q('#en-record-status');if(status)status.textContent=s.recognitionStatus;};recognizer.onend=()=>{committed=(committed+' '+cycle).trim();cycle='';interim='';ended=true;update();if(!s.running){s.recognitionDone?.();return;}if(retries<3)s.restart=setTimeout(()=>{if(s.running)try{recognizer.start();}catch{s.recognitionStatus='英文识别已中断，请结合录音回听。';}},500);};s.finishRecognition=()=>new Promise(resolve=>{if(ended){resolve();return;}s.recognitionDone=resolve;try{recognizer.stop();}catch{resolve();}setTimeout(resolve,1800);});try{recognizer.start();}catch{s.recognitionStatus='暂时无法启动英语识别，本次仍可回听。';}}
  async function start(){if(pending)return;stopPlayback();error='';if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){notify('当前浏览器不支持网页录音，请使用支持录音的独立手机浏览器');return;}pending=true;render();let stream;
    try{stream=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:true,noiseSuppression:true},video:false});if(document.hidden)throw new Error('hidden');const mime=['audio/webm;codecs=opus','audio/mp4','audio/webm','audio/ogg;codecs=opus'].find(type=>MediaRecorder.isTypeSupported?.(type));const recorder=mime?new MediaRecorder(stream,{mimeType:mime}):new MediaRecorder(stream);const s={id:crypto.randomUUID(),start:performance.now(),date:new Date().toISOString(),exercise:structuredClone(exercise()),accent:settings.accent,stream,recorder,chunks:[],samples:[],running:true,transcript:'',recognitionStatus:''};session=s;s.audioDone=new Promise(resolve=>recorder.onstop=resolve);recorder.ondataavailable=e=>{if(e.data.size)s.chunks.push(e.data);};recorder.onerror=()=>{s.recognitionStatus='录音曾中断，请检查音频是否完整。';if(s.running)stop();};recorder.start(250);pending=false;render();startRecognition(s);const Context=window.AudioContext||window.webkitAudioContext;if(Context){try{s.context=new Context();await s.context.resume();s.source=s.context.createMediaStreamSource(stream);s.analyser=s.context.createAnalyser();s.analyser.fftSize=4096;s.source.connect(s.analyser);s.frameData=new Float32Array(4096);}catch{s.analyser=null;}}sampleTime=0;const tick=now=>{if(!s.running)return;const elapsed=(now-s.start)/1000;if(q('#en-timer'))q('#en-timer').textContent=clock(elapsed);if(s.analyser&&now-sampleTime>=100){sampleTime=now;s.analyser.getFloatTimeDomainData(s.frameData);const pitch=estimatePitch(s.frameData,s.context.sampleRate);s.samples.push({t:Math.round(elapsed*10)/10,...pitch});root.querySelectorAll('.live-wave i').forEach((bar,i)=>bar.style.setProperty('--h',Math.min(25,3+pitch.rms*200*(1+i%5))+'px'));}if(elapsed>=180){notify('已练习 3 分钟，正在整理本次录音');stop();return;}s.frame=requestAnimationFrame(tick);};s.frame=requestAnimationFrame(tick);q('#en-record-caption')?.scrollIntoView({block:'nearest',behavior:'smooth'});
    }catch(e){stream?.getTracks().forEach(t=>t.stop());session=null;pending=false;error=e.name==='NotAllowedError'?'请在浏览器的网站设置中允许麦克风，再重新开始。':e.name==='NotFoundError'?'没有检测到麦克风，请检查设备后重试。':e.message==='hidden'?'请回到当前页面后重新开始。':'麦克风暂时不可用，请检查设备或其他占用麦克风的应用。';render();notify('本次尚未开始录音');}}
  async function stop(){const s=session;if(!s?.running||pending)return;pending=true;s.running=false;cancelAnimationFrame(s.frame);clearTimeout(s.restart);const duration=(performance.now()-s.start)/1000;const label=q('#en-record-caption');if(label)label.textContent='正在整理录音和纠音线索…';q('[data-en-action="record"]')?.setAttribute('disabled','');
    try{if(s.recorder.state!=='inactive')s.recorder.stop();await Promise.all([Promise.race([s.audioDone,new Promise(r=>setTimeout(r,2400))]),s.finishRecognition?.()]);try{s.recognizer?.abort();}catch{}s.stream.getTracks().forEach(t=>t.stop());await s.context?.close().catch(()=>{});const blob=new Blob(s.chunks,{type:s.recorder.mimeType||s.chunks[0]?.type||'audio/webm'});const record={id:s.id,date:s.date,exercise:s.exercise,accent:s.accent,duration:Math.round(duration*10)/10,transcript:s.transcript,analysis:evaluateEnglish({exercise:s.exercise,transcript:s.transcript,duration,samples:s.samples,recognitionStatus:s.recognitionStatus})};if(blob.size){memoryAudio.clear();memoryAudio.set(s.id,blob);record.audioSaved=await audioStore('put',s.id,blob);}else record.audioSaved=false;records.unshift(record);records.splice(30).forEach(r=>audioStore('delete',r.id));if(!persist('history',records))notify('本机存储空间不足，请下载本次录音');session=null;pending=false;render();await showReport(record);
    }catch{session=null;pending=false;error='本次录音未能保存，请检查浏览器存储后重试。';render();notify(error);}finally{s.stream.getTracks().forEach(t=>t.stop());try{s.recognizer?.abort();}catch{}if(s.context?.state!=='closed')s.context?.close().catch(()=>{});}}
  function pitchChart(pitch){if(!pitch.available)return '<p class="small-note">未获得足够稳定的音高样本。环境、低音量或无声片段都可能导致无法分析。</p>';const trace=pitch.trace,last=Math.max(trace.at(-1)?.t||1,1);let paths=[],current=[];for(const point of trace){if(point.semitone===null){if(current.length)paths.push(current.join(' '));current=[];continue;}const x=10+point.t/last*280,y=63-Math.max(-12,Math.min(12,point.semitone))*3.5;current.push(`${current.length?'L':'M'}${x.toFixed(1)},${y.toFixed(1)}`);}if(current.length)paths.push(current.join(' '));return `<div class="en-pitch-chart"><svg viewBox="0 0 300 134" role="img" aria-label="本次录音相对音高随时间的变化"><path d="M10 21H290M10 63H290M10 105H290" stroke="#dce6e6" stroke-dasharray="3 5"/>${paths.map(path=>`<path d="${path}" stroke="#517f91" stroke-width="2" fill="none"/>`).join('')}<text x="10" y="127">0s</text><text x="260" y="127">${Math.round(last)}s</text></svg></div><p class="small-note">相对本人中位音高；断线表示未检测到稳定周期。曲线未对齐示范音频，不能据此判断音准或词重音。</p>`;}
  function reportHTML(r){const a=r.analysis,direction=a.pitch.tail?.direction;return `<p class="report-kicker">ENGLISH PRACTICE REFLECTION</p><p class="report-intro"><span lang="en">${escape(r.exercise.articleTitle)}</span><br>${r.exercise.practice==='sentence'?'逐句跟读':'整段朗读'} · ${clock(r.duration)} · ${r.accent==='en-GB'?'英式':'美式'}识别${a.corrected?' · 已修正转写':''}</p><div class="en-report-metrics"><div class="report-metric"><b>${a.alignment?a.alignment.similarity+'%':'—'}</b><span>单词匹配 · 非发音分</span></div><div class="report-metric"><b>${a.wpm??'—'}</b><span>转写词 / 分钟</span></div><div class="report-metric"><b>${a.pauses.available?a.pauses.pauses.length:'—'}</b><span>较长低音量片段</span></div><div class="report-metric"><b>${a.pitch.available?a.pitch.range:'—'}</b><span>音高变化 · 半音</span></div></div>${a.usable&&!a.alignment?'<div class="notice">本组选段较长，未做单词比对。请切换到逐句跟读，获得更具体的文字线索。</div>':''}${a.recognitionStatus?`<div class="notice">${escape(a.recognitionStatus)}</div>`:''}${a.alignment&&a.words<a.alignment.referenceWords*.5?'<div class="notice">识别词数不足原文的一半，可能存在漏识别或未读完。请先回听核实。</div>':''}<div class="report-section"><h3>听见自己，再做一次调整</h3><div id="en-audio-area"><p class="small-note">正在读取本机录音…</p></div><div class="report-actions"><button class="simple-button" data-en-action="download">${icon('download')}下载录音</button><button class="simple-button primary" data-en-action="retry">${icon('refresh')}${r.exercise.practice==='sentence'?'同句再练':'同段再练'}</button></div>${r.exercise.practice==='passage'?'<button class="simple-button full mt" data-en-action="retry-sentence">拆成句子，逐句练习</button>':''}${a.pauses.pauses.length?`<div class="pause-links mt">${a.pauses.pauses.map(p=>`<button data-en-seek="${p.start}">${clock(p.start)} · ${p.duration} 秒</button>`).join('')}</div>`:''}</div><div class="report-section"><h3>这一遍，可以重点改哪里？</h3>${a.advice.map((advice,i)=>`<div class="advice-item"><span class="step-number">${i+1}</span><div><span class="en-result-kind">${advice.kind}</span><h4>${escape(advice.title)}</h4><p>${escape(advice.detail)}</p></div></div>`).join('')}</div><div class="report-section"><h3>音高与收尾 <small>录音信号线索</small></h3>${a.pitch.available?`<p class="en-pitch-description">可检测音高变化约 ${a.pitch.range} 半音${direction?`，${r.exercise.practice==='sentence'?'本句末尾':'最后片段'}走势${{rise:'上扬 ↗',fall:'下降 ↘',level:'较平稳 →'}[direction]}`:''}。</p>`:''}${pitchChart(a.pitch)}<p class="small-note">变化范围使用可检测基频的第 10—90 百分位数计算；自然窄音域不等于语调错误。这里只提供回听线索，不给语调准确度评分。</p></div>${a.alignment?`<div class="report-section"><h3>原文单词对照 <small>语音转写可能出错</small></h3><div class="diff-text en-diff" lang="en">${a.alignment.ops.map(op=>op.type==='match'?escape(op.ref):op.type==='insert'?`<mark class="insert" title="转写多出">+${escape(op.heard)}</mark>`:`<mark class="${op.type}" title="${op.type==='omit'?'转写缺少':'识别为 '+escape(op.heard)}">${escape(op.ref)}</mark>`).join(' ')}</div><p class="diff-legend">橙色：转写缺少 · 红色：转写不同 · 蓝色 +：转写多出<br>按单词编辑距离比对，比对忽略大小写和标点差异。</p>${a.alignment.mistakes.length?`<ul class="diff-list">${a.alignment.mistakes.slice(0,8).map(m=>`<li>${m.type==='omit'?'转写缺少':m.type==='insert'?'转写多出':'识别差异'}：<strong lang="en">${escape(m.ref||m.heard)}</strong>${m.type==='substitute'?` → <span lang="en">${escape(m.heard)}</span>`:''}${m.ref?` <button class="text-button" data-en-word="${escape(m.ref)}">听单词</button>`:''}</li>`).join('')}</ul>`:'<p class="small-note">本次转写与原文单词一致。文字一致不代表音素、重音或语调完全准确。</p>'}</div>`:''}<div class="report-section"><div class="report-title-line"><h3>${a.corrected?'修正后的英文转写':'本次英文转写'}</h3><button class="text-button" data-en-action="edit-transcript">修正识别</button></div><p class="transcript en-transcript mt" lang="en">${escape(r.transcript)||'未获得英文转写，仍可回听录音和查看有效的录音信号线索。'}</p><div id="en-transcript-editor"></div></div><div class="notice">基础纠音版：不检测音素或词重音准确度。请把识别差异与示范、回听结合使用；${a.corrected?'修正后的文字只用于文本比对。':'转写可能忽略重复和填充词。'}</div><button class="text-button danger full" data-en-action="delete">删除本次英语记录与录音</button>`;}
  async function showReport(r){stopPlayback();report=r;showDialog('英语跟读复盘',reportHTML(r));const blob=memoryAudio.get(r.id)||await audioStore('get',r.id);if(report?.id!==r.id||!dialog.open)return;if(audioURL)URL.revokeObjectURL(audioURL);const area=dialog.querySelector('#en-audio-area');if(blob){audioURL=URL.createObjectURL(blob);area.innerHTML=`<audio id="en-report-audio" controls preload="metadata" src="${audioURL}"></audio>${r.audioSaved?'':'<p class="small-note">录音仅在本次页面可用，请及时下载。</p>'}`;}else area.innerHTML='<p class="small-note">未找到本机录音，文字与声学摘要仍保留。</p>';}
  async function download(){if(!report)return;const blob=memoryAudio.get(report.id)||await audioStore('get',report.id);if(!blob){notify('没有找到可下载的英语录音');return;}const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=`言习-English-${report.exercise.paragraphIds.join('-')}-${report.id.slice(0,6)}.${blob.type.includes('mp4')?'m4a':blob.type.includes('ogg')?'ogg':'webm'}`;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);}
  function favorite(){const ex=exercise(),index=favorites.findIndex(f=>f.exercise.articleId===ex.articleId&&f.exercise.paragraphIds.join(',')===ex.paragraphIds.join(','));if(index>=0)favorites.splice(index,1);else{if(favorites.length>=100){notify('英语收藏已满，请先取消一组收藏');return;}favorites.unshift({id:crypto.randomUUID(),exercise:structuredClone(ex)});}if(!persist('favorites',favorites))notify('存储空间不足，收藏仅在本次页面保留');else notify(index>=0?'已取消英语选段收藏':'已收藏英语选段');render();}
  function editTranscript(){if(!report)return;dialog.querySelector('#en-transcript-editor').innerHTML=`<form id="en-correct" class="correct-form"><label for="en-correct-text">对照录音修正英文文字</label><textarea id="en-correct-text" maxlength="12000" required lang="en">${escape(report.transcript)}</textarea><p class="small-note">只更新单词比对和转写语速，录音音高与停顿保持实际测量值。</p><button type="submit" class="simple-button primary full">重新比对文字</button></form>`;dialog.querySelector('#en-correct-text').focus();}
  async function click(event){const button=event.target.closest('button');if(!button||button.disabled)return;if(button.dataset.enPractice){if(locked())return;stopPlayback();settings.practice=button.dataset.enPractice;settings.sentenceIndex=0;save();render();return;}if(button.dataset.enRecord){const r=records.find(r=>r.id===button.dataset.enRecord);if(r)showReport(r);return;}if(button.dataset.enFavorite){const f=favorites.find(f=>f.id===button.dataset.enFavorite);if(f){restore(f.exercise);render();window.scrollTo({top:0,behavior:'smooth'});}return;}if(button.dataset.enSeek){const audio=dialog.querySelector('audio');if(audio){audio.currentTime=Number(button.dataset.enSeek);audio.play().catch(()=>notify('请点击播放器回听'));}return;}if(button.dataset.enWord){speak(button.dataset.enWord);return;}const action=button.dataset.enAction;if(!action)return;if(action==='record'){if(session)await stop();else await start();return;}if(['close','download','edit-transcript','retry','retry-sentence','delete','confirm-delete'].includes(action)){}else if(locked())return;if(action==='listen')speak(exercise().text);if(action==='full-article')fullArticle();if(action==='choose')choose();if(action==='import')importForm();if(action==='close')closeDialog();if(action==='guides'){settings.guides=!settings.guides;save();render();}if(action==='favorite')favorite();if(action==='previous'||action==='next'){stopPlayback();const ex=exercise();settings.sentenceIndex=Math.max(0,Math.min(ex.sentences.length-1,ex.sentenceIndex+(action==='next'?1:-1)));save();render();}if(action==='practice'){page='practice';render();window.scrollTo({top:0,behavior:'smooth'});}if(action==='download')download();if(action==='edit-transcript')editTranscript();if((action==='retry'||action==='retry-sentence')&&report){const ex=structuredClone(report.exercise);restore(ex);if(action==='retry-sentence'){settings.practice='sentence';settings.sentenceIndex=0;save();}closeDialog();render();window.scrollTo({top:0,behavior:'smooth'});}if(action==='delete'&&report){dialog.querySelector('#en-transcript-editor').innerHTML='<div class="notice mt">这将永久删除本次英语记录和本机录音。<button class="simple-button danger full mt" data-en-action="confirm-delete">确认删除</button></div>';dialog.querySelector('#en-transcript-editor').scrollIntoView({block:'center',behavior:'smooth'});}if(action==='confirm-delete'&&report){const id=report.id;records=records.filter(r=>r.id!==id);persist('history',records);await audioStore('delete',id);memoryAudio.delete(id);closeDialog();render();notify('已删除本次英语练习');}}
  function change(event){if(event.target.id==='en-accent'||event.target.id==='en-rate'){if(locked()){event.target.value=event.target.id==='en-accent'?settings.accent:String(settings.rate);return;}stopPlayback();if(event.target.id==='en-accent')settings.accent=event.target.value;else settings.rate=Number(event.target.value);save();render();}if(event.target.id==='en-article-select'){const id=event.target.value,a=[ARTICLE,...articles,temporaryArticle].find(item=>item?.id===id)||ARTICLE;choose(id,id===ARTICLE.id?DEFAULT_PARAGRAPHS:a.paragraphs.slice(0,2).map(p=>p.id));}if(event.target.matches('#en-selection input[type="checkbox"]')&&dialog.querySelectorAll('input[name="paragraph"]:checked').length>2){event.target.checked=false;notify('每次最多选两个自然段');}}
  function submit(event){if(event.target.id==='en-selection'){event.preventDefault();const selection=new FormData(event.target),ids=selection.getAll('paragraph').map(Number);if(ids.length<1||ids.length>2){notify('请选择一到两个自然段');return;}settings.articleId=selection.get('article');settings.paragraphIds=ids;settings.sentenceIndex=0;save();closeDialog();render();notify('已换好英语选段');}if(event.target.id==='en-import'){event.preventDefault();if(articles.length>=10){notify('已保存 10 篇自录文章，请先使用现有文章');return;}try{const a=parseImportedArticle(dialog.querySelector('#en-import-title').value,dialog.querySelector('#en-import-text').value);articles.unshift(a);if(!persist('articles',articles))notify('存储空间不足，文章仅在本次页面保留');settings.articleId=a.id;settings.paragraphIds=a.paragraphs.slice(0,2).map(p=>p.id);settings.sentenceIndex=0;save();render();choose();notify('文章已录入，请选择自然段');}catch(e){notify(e.message);}}if(event.target.id==='en-correct'){event.preventDefault();if(!report)return;const transcript=dialog.querySelector('#en-correct-text').value.trim();if(!englishTokens(transcript).length){notify('请输入有效英文文字');return;}report.transcript=transcript;report.analysis=evaluateEnglish({exercise:report.exercise,transcript,duration:report.duration,acoustic:report.analysis,corrected:true,recognitionStatus:report.analysis.recognitionStatus});persist('history',records);showReport(report);}}
  root.addEventListener('click',click);root.addEventListener('change',change);dialog.addEventListener('click',click);dialog.addEventListener('change',change);dialog.addEventListener('submit',submit);dialog.addEventListener('click',event=>{if(event.target===dialog){const rect=dialog.getBoundingClientRect();if(event.clientX<rect.left||event.clientX>rect.right||event.clientY<rect.top||event.clientY>rect.bottom)closeDialog();}});dialog.addEventListener('close',()=>{dialog.querySelector('audio')?.pause();if(audioURL){URL.revokeObjectURL(audioURL);audioURL=null;}report=null;});document.addEventListener('visibilitychange',()=>{if(document.hidden){stopPlayback();if(session?.running)stop();}});window.addEventListener('beforeunload',()=>{session?.stream.getTracks().forEach(t=>t.stop());try{session?.recognizer?.abort();}catch{}});
  return {render,isBusy,stopPlayback,help};
}
